def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 2 and all(
                grid[rr][cc] == 3
                for rr in range(r - 1, r + 2)
                for cc in range(c - 1, c + 2)
                if (rr, cc) != (r, c)
            ):
                centers.append((r, c))

    if not centers:
        return out

    row_counts = [sum(v == 2 for v in row) for row in grid]
    col_counts = [sum(grid[r][c] == 2 for r in range(h)) for c in range(w)]
    row_score = max(row_counts)
    col_score = max(col_counts)

    # The long 2-lines are parallel rails; propagate perpendicular to them.
    horizontal_rails = row_score >= col_score
    if horizontal_rails:
        rails = [r for r, n in enumerate(row_counts) if n >= w / 2]
        for r, c in centers:
            for rr in range(h):
                if out[rr][c] == 0:
                    out[rr][c] = 1
            for rail in rails:
                if rail == r:
                    continue
                for rr in range(rail - 1, rail + 2):
                    for cc in range(c - 1, c + 2):
                        if 0 <= rr < h and 0 <= cc < w and (rr, cc) != (rail, c):
                            out[rr][cc] = 1
    else:
        rails = [c for c, n in enumerate(col_counts) if n >= h / 2]
        for r, c in centers:
            for cc in range(w):
                if out[r][cc] == 0:
                    out[r][cc] = 1
            for rail in rails:
                if rail == c:
                    continue
                for rr in range(r - 1, r + 2):
                    for cc in range(rail - 1, rail + 2):
                        if 0 <= rr < h and 0 <= cc < w and (rr, cc) != (r, rail):
                            out[rr][cc] = 1

    return out
